import 'package:flutter_test/flutter_test.dart';
import 'package:musly/models/playlist.dart';

void main() {
  Playlist read(Map<String, dynamic> json) =>
      Playlist.fromJson({'name': 'List', ...json});

  group('Playlist', () {
    test('recognizes the mixes and radios Octo makes', () {
      final mix = read({
        'id': 'og9gl0dJcwlc38Dfqcnmmh',
        'readonly': true,
        'validUntil': '2026-10-27T11:59:49.868Z',
        'comment': 'Generated by Octo from your library',
      });
      final radio = read({'id': 'orikrHIUVhthov8h5LYnsw', 'readonly': true});
      expect(mix.isOctoMix, isTrue);
      expect(mix.isAutomatic, isTrue);
      expect(mix.validUntil, DateTime.utc(2026, 10, 27, 11, 59, 49, 868));
      expect(radio.isOctoMix, isTrue);
    });

    test("keeps Navidrome's lists and the user's playlists apart", () {
      // Navidrome's own read-only list: automatic, but not an Octo mix.
      final recent = read({'id': '1LV2quzTZugQLMlmoYA4GZ', 'readonly': true});
      expect(recent.isAutomatic, isTrue);
      expect(recent.isOctoMix, isFalse);

      // A playlist of the user whose id happens to start with "or".
      final own = read({'id': 'orXXXXXXXXXXXXXXXXXXXX', 'readonly': false});
      expect(own.isOctoMix, isFalse);
      expect(own.isAutomatic, isFalse);
    });

    test('reads readonly sent as text', () {
      expect(read({'id': 'a', 'readonly': 'true'}).readonly, isTrue);
      expect(read({'id': 'a'}).readonly, isNull);
    });

    test('keeps the new fields through toJson', () {
      final mix = read({
        'id': 'og9gl0dJcwlc38Dfqcnmmh',
        'readonly': true,
        'validUntil': '2026-10-27T11:59:49.868Z',
      });
      final again = Playlist.fromJson(mix.toJson());
      expect(again.isOctoMix, isTrue);
      expect(again.validUntil, mix.validUntil);
    });

    test("recognizes Octo's liked songs playlist, not one named alike", () {
      expect(
        read({'id': 'a', 'name': 'Titres likés', 'readonly': true})
            .isServerLikedSongs,
        isTrue,
      );
      // Made by hand with the same name: kept.
      expect(read({'id': 'a', 'name': 'Titres likés'}).isServerLikedSongs,
          isFalse);
      expect(
        read({'id': 'a', 'name': 'Top France', 'readonly': true})
            .isServerLikedSongs,
        isFalse,
      );
    });

    test('only offers its own, hand-made playlists to add songs to', () {
      expect(read({'id': 'a', 'owner': 'lea'}).isEditableBy('lea'), isTrue);
      expect(read({'id': 'a', 'owner': 'Lea'}).isEditableBy('lea'), isTrue);
      // Shared by someone else: the server would refuse.
      expect(read({'id': 'a', 'owner': 'max'}).isEditableBy('lea'), isFalse);
      // Made by the server.
      expect(
        read({'id': 'a', 'owner': 'lea', 'readonly': true}).isEditableBy('lea'),
        isFalse,
      );
      expect(read({'id': 'a'}).isEditableBy(null), isTrue);
    });
  });
}
